-- ============================================
-- LUMA — Enrichissement Thématique 14 (Road trip USA) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"friend": "ton compagnon de route"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "First stop, Nashville! Music city, here we come.", "text_fr": "Premier arrêt, Nashville ! La ville de la musique, nous voilà.", "choices": [{"text": "Let''s find some live music tonight.", "next": "n2"}, {"text": "Let''s check out the food scene first.", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "(after Nashville) On to New Orleans next, though there''s a storm warning.", "text_fr": "(après Nashville) Direction La Nouvelle-Orléans ensuite, même s''il y a une alerte tempête.", "choices": [{"text": "Let''s take an alternate route to be safe.", "next": "n3"}, {"text": "Let''s push through, we can''t lose too much time.", "next": "n3b"}]}, "n2b": {"speaker": "friend", "text": "Good call, that hot chicken place was legendary. On to New Orleans next, though there''s a storm warning.", "text_fr": "Bien vu, ce resto de poulet épicé était légendaire. Direction La Nouvelle-Orléans ensuite, même s''il y a une alerte tempête.", "choices": [{"text": "Let''s take an alternate route to be safe.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "Good call, we avoided the worst of it. Final stop: the coast!", "text_fr": "Bonne décision, on a évité le pire. Dernier arrêt : la côte !", "choices": [{"text": "Let''s find a nice spot to watch the sunset there.", "next": "n4"}]}, "n3b": {"speaker": "friend", "text": "(the storm catches you, a scary but manageable drive) That was intense, but we made it through!", "text_fr": "(la tempête vous rattrape, une conduite effrayante mais gérable) C''était intense, mais on s''en est sortis !", "choices": [{"text": "Lesson learned — let''s be more careful for the rest of the trip.", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "We''re almost at our final destination. What''s the highlight of this trip for you?", "text_fr": "On est presque à destination finale. Quel a été le point fort de ce voyage pour toi ?", "choices": [{"text": "Honestly, just the freedom of the open road with you.", "next": "n5"}, {"text": "That storm we survived, oddly enough — it brought us closer.", "next": "n5b"}]}, "n5": {"speaker": "friend", "text": "That means a lot to hear. This trip has honestly exceeded my expectations.", "text_fr": "Ça compte beaucoup d''entendre ça. Ce voyage a honnêtement dépassé mes attentes.", "choices": [{"text": "Same here — what an unforgettable adventure!", "next": "end_journey"}]}, "n5b": {"speaker": "friend", "text": "Ha, funny how the scary moments become the best stories.", "text_fr": "Ha, drôle de voir comment les moments effrayants deviennent les meilleures histoires.", "choices": [{"text": "That''s the magic of a real road trip.", "next": "end_journey"}]}, "end_journey": {"speaker": "friend", "text": "Same here — what an unforgettable adventure!", "text_fr": "Pareil pour moi — quelle aventure inoubliable !", "end": true, "ending_label": "Road trip épique achevé 🛣️"}}}'::jsonb, is_playable = true
where title = 'Un road trip complet sur plusieurs villes avec péripéties'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"traveler": "un autre voyageur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "traveler", "text": "Mind if I join you at this table? Traveling solo can get lonely.", "text_fr": "Ça vous dérange si je me joins à vous ? Voyager seul peut devenir solitaire.", "choices": [{"text": "Not at all, please sit! Where are you headed?", "next": "n2"}, {"text": "Actually, I was just leaving — but nice to meet you briefly.", "next": "n2b"}]}, "n2": {"speaker": "traveler", "text": "West coast, eventually. You?", "text_fr": "La côte ouest, éventuellement. Et vous ?", "choices": [{"text": "Same direction actually — want to travel together for a bit?", "next": "n3"}]}, "n2b": {"speaker": "traveler", "text": "Oh, no worries at all, have a safe trip!", "text_fr": "Oh, pas de souci, bon voyage !", "choices": [{"text": "(you leave, but keep thinking about the missed connection)", "next": "end_missed"}]}, "n3": {"speaker": "traveler", "text": "I''d really love that, this trip just got a lot better.", "text_fr": "J''adorerais ça, ce voyage vient de s''améliorer énormément.", "choices": [{"text": "Same here, safety and fun in numbers!", "next": "n4"}]}, "n4": {"speaker": "traveler", "text": "(days later, after sharing stories on the road) I feel like I''ve known you for years already.", "text_fr": "(des jours plus tard, après avoir partagé des histoires sur la route) J''ai l''impression de vous connaître depuis des années déjà.", "choices": [{"text": "Same here, this trip wouldn''t have been the same without you.", "next": "n5"}]}, "n5": {"speaker": "traveler", "text": "Let''s promise to stay in touch after this, wherever life takes us.", "text_fr": "Promettons de rester en contact après ça, où que la vie nous mène.", "choices": [{"text": "Absolutely, this friendship is too good to lose.", "next": "end_friendship"}]}, "end_missed": {"speaker": "traveler", "text": "(you never see them again, but often wonder what could have been)", "text_fr": "(vous ne les revoyez jamais, mais vous vous demandez souvent ce qui aurait pu être)", "end": true, "ending_label": "Une connexion manquée, un souvenir fugace 🚶"}, "end_friendship": {"speaker": "traveler", "text": "To new friendships and open roads!", "text_fr": "Aux nouvelles amitiés et aux routes ouvertes !", "end": true, "ending_label": "Amitié de voyage née et scellée 🚗💛"}}}'::jsonb, is_playable = true
where title = 'Une amitié qui se noue en chemin'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"officer": "un policier local"}, "start_node": "n1", "nodes": {"n1": {"speaker": "officer", "text": "Sir/Ma''am, your car was reported for a broken taillight. License and registration, please.", "text_fr": "Monsieur/Madame, votre voiture a été signalée pour un feu arrière cassé. Permis et carte grise, s''il vous plaît.", "choices": [{"text": "Here you go, officer. I wasn''t aware, I''ll get it fixed right away.", "next": "n2"}, {"text": "I''m a tourist, I''m not sure I understand the issue fully.", "next": "n2b"}]}, "n2": {"speaker": "officer", "text": "I appreciate your cooperation. I''ll let you off with a warning this time.", "text_fr": "J''apprécie votre coopération. Je vous laisse un avertissement cette fois.", "choices": [{"text": "Thank you so much, I''ll have it repaired at the next town.", "next": "n3"}]}, "n2b": {"speaker": "officer", "text": "No worries — your right taillight isn''t working. It''s a safety issue.", "text_fr": "Pas de souci — votre feu arrière droit ne fonctionne pas. C''est un problème de sécurité.", "choices": [{"text": "Ah, I understand now, thank you for explaining clearly.", "next": "n3"}]}, "n3": {"speaker": "officer", "text": "Actually, there''s a mechanic shop just two miles from here, open until 6pm.", "text_fr": "En fait, il y a un garage à seulement trois kilomètres d''ici, ouvert jusqu''à 18h.", "choices": [{"text": "That''s very helpful, thank you for the tip!", "next": "n4"}]}, "n4": {"speaker": "officer", "text": "No problem. Where are you folks headed on this trip?", "text_fr": "Pas de problème. Vous allez où sur ce voyage ?", "choices": [{"text": "We''re doing a full coast-to-coast road trip actually.", "next": "n5"}]}, "n5": {"speaker": "officer", "text": "That''s quite the adventure! Drive safe, and enjoy the rest of your trip.", "text_fr": "Quelle aventure ! Conduisez prudemment, et profitez bien de la suite de votre voyage.", "choices": [{"text": "Thank you, I really appreciate your help today.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "officer", "text": "Sounds good, drive safe out there.", "text_fr": "Parfait, conduisez prudemment.", "end": true, "ending_label": "Imprévu géré entièrement en anglais, avec le sourire 🚓"}}}'::jsonb, is_playable = true
where title = 'Un imprévu majeur à résoudre entièrement en anglais'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
